fix.code:
@Bean
SecurityFilterChain web(HttpSecurity http) throws Exception {
    http
        .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
        .formLogin(withDefaults());
    // Không gọi csrf(...): CSRF bật mặc định, token lưu trong session.
    // Form Thymeleaf có th:action tự chèn input _csrf; thiếu hoặc sai token thì 403.
    // App không cần cho trang khác đọc response, nên bỏ hẳn cấu hình CORS.
    return http.build();
}

@PostMapping("/account/email")
String changeEmail(@AuthenticationPrincipal UserDetails user,
                   @RequestParam("email") String email,
                   @RequestParam("currentPassword") String currentPassword) {
    accountService.changeEmail(user.getUsername(), email, currentPassword); // xác thực lại, báo về email cũ
    return "redirect:/account";
}

